<?php require '../config/database.php';require '../includes/auth.php';require_admin();if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM feedback WHERE id=?')->execute([(int)$_GET['delete']]);flash('success','Feedback removed.');header('Location: feedback.php');exit;}$base_path='../';$page_title='Manage Feedback';$feedback=$pdo->query('SELECT * FROM feedback ORDER BY created_at DESC')->fetchAll();include '../includes/header.php'; ?>
<section class="container py-5"><h1 class="section-title mb-4">Manage feedback</h1><div class="card p-3 table-responsive"><table class="table align-middle"><thead><tr><th>Name</th><th>Email</th><th>Message</th><th>Date</th><th></th></tr></thead><tbody><?php foreach($feedback as $item): ?><tr><td><?= htmlspecialchars($item['name']) ?></td><td><?= htmlspecialchars($item['email']) ?></td><td><?= nl2br(htmlspecialchars($item['message'])) ?></td><td><?= date('d M Y',strtotime($item['created_at'])) ?></td><td><a class="btn btn-sm btn-outline-danger" data-confirm="Delete this feedback?" href="feedback.php?delete=<?= $item['id'] ?>">Delete</a></td></tr><?php endforeach; ?><?php if(!$feedback): ?><tr><td colspan="5" class="text-center text-muted">No feedback received yet.</td></tr><?php endif; ?></tbody></table></div></section><?php include '../includes/footer.php'; ?>
